#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
_Static_assert(BLKGETSIZE64 == 0x80081272, "BLKGETSIZE64 ABI");
_Static_assert(DM_LIST_DEVICES == 0xc138fd02, "DM_LIST_DEVICES ABI");
_Static_assert(sizeof(struct dm_ioctl) == 312 && offsetof(struct dm_ioctl, data_size) == 12 && offsetof(struct dm_ioctl, data_start) == 16, "dm_ioctl ABI");
_Static_assert(sizeof(struct dm_name_list) == 16 && offsetof(struct dm_name_list, name) == 12, "dm_name_list ABI");
_Static_assert(CAP_CHOWN == 0 && CAP_NET_RAW == 13 && VFS_CAP_REVISION_2 == 0x02000000, "cap ABI");

/* Prove the caller installed this fixture's supervisor before any operation
   on a clock, device, or writable control. The sentinel is a regular file;
   without the mock its private ioctl cannot return this synthetic value. */
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>
static int parity_mock_is_installed(void) {
  struct stat st; int fd=open("mock-sentinel",O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK);
  if (fd<0) return 0;
  if (fstat(fd,&st) || !S_ISREG(st.st_mode) || st.st_nlink!=1) { close(fd); return 0; }
  int result=ioctl(fd,0xdead5a17UL,0UL);
  int closed=close(fd);
  if (closed || result!=987654321) { fputs("mock supervisor required\n",stderr); return 0; }
  return 1;
}
static int parity_lacks_cap(unsigned bit) {
  FILE *f=fopen("/proc/self/status","r"); char line[256]; unsigned long long caps=0; int found=0;
  if (!f) return 0;
  while (fgets(line,sizeof line,f))
    if (sscanf(line,"CapEff: %llx",&caps)==1) { found=1; break; }
  fclose(f);
  return found && bit<64 && !(caps & (1ULL<<bit));
}

int main(int argc, char **argv) {
  if (!parity_require_guest()) return 125;
  if (!parity_mock_is_installed()) return 125;
  if (argc != 2) return 10;
  if (!strcmp(argv[1], "block")) {
    uint64_t n=0; int fd=open("target",O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK); struct stat private_file;
    if(fd<0 || fstat(fd,&private_file) || !S_ISREG(private_file.st_mode) || ioctl(fd,BLKGETSIZE64,&n) || n!=1000 || close(fd)) return 11;
  } else if (!strcmp(argv[1], "caps")) {
    uint32_t got[3]={0}; ssize_t n=getxattr("target","security.capability",got,sizeof got);
    if(n!=12 || got[0]!=0x02000001 || got[1]!=1 || got[2]!=(1u<<13)) return 12;
  } else if (!strcmp(argv[1], "dm")) {
    union { struct dm_ioctl aligned; unsigned char bytes[4096]; } u = {0};
    unsigned char *buf=u.bytes; struct dm_ioctl *h=(struct dm_ioctl *)buf;
    int fd=open("/dev/mapper/control",O_RDWR|O_CLOEXEC); struct stat private_file;
    if(fd<0 || fstat(fd,&private_file) || !S_ISREG(private_file.st_mode) || ioctl(fd,DM_LIST_DEVICES,h)) return 13;
    if(h->data_start!=312 || h->data_size!=329) return 14;
    struct dm_name_list *n=(struct dm_name_list *)(buf+h->data_start);
    if (n->next || major(n->dev)!=253 || minor(n->dev)!=1 || strcmp(n->name,"good") || close(fd)) return 15;
  } else if (!strcmp(argv[1], "dm-denied")) {
    errno=0; int fd=open("/dev/mapper/control",O_RDWR|O_CLOEXEC);
    if (fd>=0) { close(fd); return 17; }
    if (errno!=EPERM) return 18;
  } else return 16;
  puts("probe ok"); return 0;
}

